pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(address actor, uint256 amount, uint256 collectAmt) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 1e30);
        collectAmt = bound(collectAmt, 0, amount - 1);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        // move strictly past the unlock time set by Put
        vm.warp(block.timestamp + 1);

        vm.prank(actor);
        try c.Collect{value: 0}(collectAmt) {
            // rule: after depositing v and withdrawing any a < v,
            // the recorded balance is exactly v - a.
            assertTrue(c.Acc(actor).balance == amount - collectAmt);
        } catch {
            // withdrawal not permitted (e.g. counterparty cannot receive):
            // recorded balance must still be the full deposit v.
            assertTrue(c.Acc(actor).balance == amount);
        }
    }
}

