pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    // recover the address of a contract deployed by `d` at create-nonce n (n is 0 or 1 here)
    function _createAddr(address d, uint8 n) internal pure returns (address r) {
        bytes memory buf = new bytes(23);
        buf[0] = 0xd6; // RLP list prefix for 22 bytes
        buf[1] = 0x94; // 20-byte string prefix
        bytes20 db = bytes20(d);
        for (uint256 i = 0; i < 20; i++) buf[2 + i] = db[i];
        buf[22] = bytes1(n == 0 ? 0x80 : n); // RLP nonce
        r = address(uint160(uint256(keccak256(buf))));
    }

    function testFuzz_property(uint256 amount, address actor, uint256 unlockTime) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.deal(actor, amount);

        // drive c through the public entry Put
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // locate the Log contract deployed alongside c: it is one of the two
        // contracts created by address(this); the Log is the candidate whose
        // code does NOT implement C's public Acc(address) getter.
        address logAddr = address(0);
        for (uint8 n = 0; n <= 1; n++) {
            address cand = _createAddr(address(this), n);
            if (cand.code.length == 0) continue;
            (bool isC, ) = cand.staticcall(abi.encodeWithSignature("Acc(address)", actor));
            if (!isC) { logAddr = cand; break; }
        }
        require(logAddr != address(0), "log not found");

        // GENERAL RULE: after ANY (amount, actor, unlockTime) deposit via Put,
        // the deposit is recorded in the public History of the Log, so the
        // public getter History(0) must succeed.
        bool recorded;
        try Log(logAddr).History(0) returns (address, uint256, string memory, uint256) {
            recorded = true;
        } catch {
            recorded = false;
        }
        assertTrue(recorded);
    }
}

