pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        Log log = new Log();
        c = new C(address(log));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 1000 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        // General rule: every successful deposit is recorded in the log's
        // public History with the depositor as Sender and the amount as Val.
        bool recorded = false;
        address logAddr = address(c.Acc(actor) == c.Acc(actor) ? address(0) : address(0));
        logAddr;
        // Probe the History of the log attached to c by replaying the same
        // calls c makes: c's LogFile is internal, so we recover entries via
        // the Log we deployed with the same address we passed to c.
        // Re-derive it: we passed a fresh Log in setUp; recover via low-level
        // history probing on that instance is not directly reachable here,
        // so instead observe through c's own behavior mirror: we re-read the
        // log through a second identical Put on a probe log is not allowed;
        // simplest public observation: History accessor revert-probing is the
        // tried path, so we instead assert on the recorded balance AND that
        // the log at the address given to c contains the entry, by scanning
        // History entries until revert.
        Log attached = Log(_logAddressOfC());
        for (uint256 i = 0; i < 64 && !recorded; i++) {
            try attached.History(i) returns (address sender, string memory, uint256 val, uint256) {
                if (sender == actor && val == amount) {
                    recorded = true;
                }
            } catch {
                break;
            }
        }
        assertTrue(recorded);
    }

    // The Log instance handed to c in setUp is the only Log deployed before
    // c; recover it deterministically: we cannot read c's private LogFile,
    // so we track it via this test-scoped address computed at construction.
    address private _log;

    function _logAddressOfC() internal returns (address) {
        if (_log == address(0)) {
            // First call: locate the Log by trying AddMessage-through probe is
            // intrusive; instead rely on setUp order — the Log was created
            // immediately before c, so it is at a lower nonce address. We
            // simply re-deploy tracking here is not possible; fallback: the
            // assertion path needs the exact instance, so we track it by
            // calling Put once more is not needed. Resolve by scanning known
            // precomputed addresses is fragile — use eth-level trick:
            // compute address of Log deployed right before c in setUp.
            _log = address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xd6), bytes1(0x94), address(this), uint64(0))))) - 1);
        }
        return _log;
    }
}

