    function testFuzz_property(uint256 amount, address actor, uint256 unlockTime) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount < 1e30);
        bound(unlockTime, 0, 1e12);

        // obtain the log address by reading it through the contract's public surface:
        // the Log was created in setUp; re-derive it by calling a Put and reading History later.
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // Read the Log's public History: after any Put, entry 0 must exist and record the exact amount.
