pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public {
        log = new Log();
        c = new C(address(log));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(log));
        amount = bound(amount, 0, address(this).balance > 0 ? address(this).balance : 1 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        bool ok;
        address sender;
        string memory data;
        uint256 val;
        uint256 time;
        try log.History(0) returns (address s, string memory d, uint256 v, uint256 t) {
            ok = true;
            sender = s;
            data = d;
            val = v;
            time = t;
        } catch {
            ok = false;
        }

        assertTrue(
            ok && sender == actor && val == amount &&
            keccak256(bytes(data)) == keccak256(bytes("Put")) && time == block.timestamp,
            "every successful Put must record an entry in the Log's History matching depositor, amount, data and time"
        );
    }
}

contract InvMutTest {
    C c;
    uint amt;
    bool reentered;

    constructor(C _c) { c = _c; }

    function test(uint amount) public {
        require(amount >= 1 ether);
        require(address(this).balance >= amount);
        amt = amount;
        c.Put{value: amount}(0); // unlockTime = now, balance = amount >= MinSum
        c.Collect(amount);       // pays out; reentrant 2nd Collect must fail on P
        assert(address(this).balance == amount);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            (bool ok, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", amt));
            ok; // swallow revert: on P the mutex makes this reentry fail
        }
    }

    fallback() external payable {}
}

