contract InvMutTest {
    C c;
    bool reentrantReverted;
    bool inCollect;
    uint pendingAmt;

    constructor(C _c) { c = _c; }

    function run(uint amount, uint unlockTime) public payable {
        require(address(this).balance >= amount);
        require(amount >= c.MinSum());

        // deposit funds with an unlock time in the past so Collect is allowed
        c.Put{value: amount}(unlockTime);

        reentrantReverted = false;
        pendingAmt = amount;
        inCollect = true;
        bool reverted;
        try c.Collect{value: 0}(amount) { reverted = false; } catch { reverted = true; }
        inCollect = false;

        // In P: during the payout the mutex is held, so the reentrant Collect
        // triggered from receive() reverts.  In M the mutex is never set and
        // the reentrant Collect succeeds, making reentrantReverted false.
        assert(reverted == false && reentrantReverted == true);
    }

    receive() external payable {
        if (inCollect) {
            inCollect = false;
            try c.Collect{value: 0}(pendingAmt) { /* succeeds only in mutant */ } catch { reentrantReverted = true; }
        }
    }
}

contract InvMutTest {
    C c;
    uint reentryAmt;

    constructor(C _c) { c = _c; }

    function run(uint amount, uint am) public payable {
        require(amount >= 1 ether);
        require(am > 0 && am <= amount);
        require(address(this).balance >= amount);
        c.Put{value: amount}(0);
        reentryAmt = am;
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        reentryAmt = 0;
        (, uint bal) = c.Acc(address(this));
        assert(bal >= amount - am);
    }

    receive() external payable {
        if (reentryAmt > 0) {
            c.Collect(reentryAmt);
            reentryAmt = 0;
        }
    }
}
